from abq_authoring import *
start(2011,'Clothes-4-Us Ltd',6,[5])
add('a-i','Define the management activity of ‘planning’.',6,'business-2-13','definition-of-planning',['The definition carries 3 + 3 marks for goals/objectives and strategies for achieving them.'],[response(1,'Definition',[('explain','Goals and objectives',3),('develop','Strategies to achieve them',3)])],[18],[])
add('a-ii','Illustrate how different types of planning benefit Clothes-4-Us Ltd.',14,'business-2-13','benefits-of-planning',['Illustrate two types of planning and their benefits, with relevant case links. Each carries 7 marks.'],[response(i,f'Type of planning {i}',[('name','State',2),('explain','Benefit / explanation',3),('link','Relevant link',2)]) for i in [1,2]],[18,19])
add('b','Evaluate the effectiveness of the Human Resource department at Clothes-4-Us Ltd.',30,'business-3-20','effectiveness-of-human-resource-management',['Discuss three HR functions at 9 marks each. Give an informed evaluation based on the case for the remaining 3 marks.'],[response(i,f'HR function {i}',[('name','Function',3),('explain','Explanation',3),('link','Separate relevant link',3)]) for i in [1,2,3]]+[response(4,'Evaluation',[('evaluate','Informed judgement',3)])],[19,20])
add('c-i','Explain the term ‘Market Research’.',6,'business-4-16','definition-of-market-research',['The explanation carries 3 + 3 marks. Use the support notes to assess the gathering, recording and analysis of information to identify and satisfy customer needs.'],[response(1,'Definition',[('explain','First element of explanation',3),('develop','Second element of explanation',3)])],[21],[])
add('c-ii','Analyse how Desk and Field Research can contribute to the continued success of Clothes-4-Us Ltd.',24,'business-4-16','desk-and-field-research',['Analyse both desk and field research, including their contribution to success and relevant case links.','Each research approach carries 12 marks (6 + 6). The summary does not label those two six-mark components; use the full support notes when assessing the analysis.'],[response(i,label,[('explain','First six-mark component',6),('develop','Second six-mark component',6)]) for i,label in enumerate(['Desk research','Field research'],1)],[21,22],['Refer to the relevant theory, contributions and case links shown on the attached official scheme pages.'])
finish({'A(i)':6,'A(ii)':14,'B':30,'C(i)':6,'C(ii)':24},[18,19,20,21,22],'There is no finite printed choose-k menu. Planning types and HR functions are open examples. Desk and field research are both required in C(ii), so their headings remain one response rather than alternative routes.', ['Part A splits at 6/14 and C at 6/24.','C(ii) retains the published 12 (6+6) marks per research approach. The summary does not expressly label the two six-mark components, so no invented theory/link tariff is imposed.','Scheme PDF pages are two greater than printed numbers.'])
